#[tokio::test]
async fn search_set_honours_match_options() {
    // Helper: set the search and return the total match count for the given options.
    async fn total(ws: &mut Ws, buffer_id: u64, q: &str, options: MatchOptions) -> u32 {
        let r: SearchSetResult = send_request::<SearchSet>(
            ws,
            &SearchSetParams {
                view_id: view_of(buffer_id),
                query: q.into(),
                anchor: None,
                extend: false,
                from_selection: false,
                options,
            },
        )
        .await;
        r.summary.total
    }

    // Case: smartcase (lowercase query) matches all three; forced-sensitive matches only the two
    // lowercase runs; forced-insensitive matches all three again.
    let (server, mut ws, buffer_id) = setup_with_buffer("foo Foo foo\n").await;
    assert_eq!(
        total(&mut ws, buffer_id, "foo", MatchOptions::default()).await,
        3
    );
    let sensitive = MatchOptions {
        case: CaseMode::Sensitive,
        ..Default::default()
    };
    assert_eq!(total(&mut ws, buffer_id, "foo", sensitive).await, 2);
    let insensitive = MatchOptions {
        case: CaseMode::Insensitive,
        ..Default::default()
    };
    assert_eq!(total(&mut ws, buffer_id, "Foo", insensitive).await, 3);
    drop(server);

    // Whole-word: "foo" inside "foobar" is excluded once word boundaries are required.
    let (server, mut ws, buffer_id) = setup_with_buffer("foo foobar foo\n").await;
    assert_eq!(
        total(&mut ws, buffer_id, "foo", MatchOptions::default()).await,
        3
    );
    let word = MatchOptions {
        whole_word: true,
        ..Default::default()
    };
    assert_eq!(total(&mut ws, buffer_id, "foo", word).await, 2);
    drop(server);

    // Regex opt-in: "a.c" matches literally by default (only "a.c"); with `regex` it matches
    // "abc"/"axc" too.
    let (server, mut ws, buffer_id) = setup_with_buffer("a.c abc axc\n").await;
    assert_eq!(
        total(&mut ws, buffer_id, "a.c", MatchOptions::default()).await,
        1,
        "literal is the default — a.c matches only a.c"
    );
    let regex = MatchOptions {
        regex: true,
        ..Default::default()
    };
    assert_eq!(total(&mut ws, buffer_id, "a.c", regex).await, 3);
    // Literal (default) + whole-word together don't double-escape: "a.c" still matches as a word.
    let literal_word = MatchOptions {
        whole_word: true,
        ..Default::default()
    };
    assert_eq!(total(&mut ws, buffer_id, "a.c", literal_word).await, 1);
    drop(server);
}

