/// nav/goto restores a closed file by path (its buffer_id is long gone) with the saved cursor,
/// without touching the back/forward stacks. Models the web client's `popstate` restore.
#[tokio::test]
async fn nav_goto_reopens_by_path() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("a.txt"), "one\ntwo\nthree\n").unwrap();
    let server = spawn_for_test("test-proj", vec![dir.path().to_path_buf()])
        .await
        .unwrap();
    let mut ws = Ws::connect(&server).await;
    let _: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "test-proj".into(),
            open_last: false,
        },
    )
    .await;
    let (buf_a, _) = nav_open_file(&mut ws, "a.txt", None).await;
    // Close it so the stale buffer_id forces the path fallback.
    send_request::<ViewClose>(
        &mut ws,
        &ViewCloseParams {
            view_id: view_of(buf_a),
            open_next: false,
        },
    )
    .await;

    let res: NavStepResult = send_request::<NavGoto>(
        &mut ws,
        &NavGotoParams {
            virtual_key: None,
            read: None,
            view_id: Some(view_of(buf_a)), // stale on purpose
            path_index: Some(0),
            relative_path: Some("a.txt".into()),
            cursor: CursorState {
                position: LogicalPosition { line: 2, col: 1 },
                anchor: LogicalPosition { line: 2, col: 1 },
                match_bracket: None,
                jumplist_position: None,
            },
        },
    )
    .await;
    let target = res.target.expect("goto should open the file");
    assert_eq!(
        target.path.as_deref().map(|p| p.ends_with("a.txt")),
        Some(true)
    );
    assert_eq!(target.cursor.position, LogicalPosition { line: 2, col: 1 });
    drop(server);
}

// ---- nav history is per (context, client) --------------------------------------------------
//
// A nav entry names its file as `(path_index, relative_path)` *relative to the roots of the
// workspace that recorded it*, so a trail shared across workspaces resolves its entries against
// the wrong roots. These pin the ownership that fixes it: one trail per (context, client), plus
// the copy a context keeps of the last trail to leave it.

/// Two workspaces on one server, each rooted at a directory of its own — `proj-a` holding
/// `a1..a3.txt`, `proj-b` holding `b1..b2.txt`. Both roots are `path_index: 0` of their own
/// workspace, which is exactly the collision a cross-workspace trail used to fall into.
async fn two_workspaces() -> aether_server::ServerHandle {
    let dir_a = tempfile::tempdir().unwrap();
    for (name, content) in [
        ("a1.txt", "alpha\nsecond\n"),
        ("a2.txt", "another\n"),
        ("a3.txt", "again\n"),
    ] {
        std::fs::write(dir_a.path().join(name), content).unwrap();
    }
    let dir_b = tempfile::tempdir().unwrap();
    for (name, content) in [("b1.txt", "bravo\n"), ("b2.txt", "beta\n")] {
        std::fs::write(dir_b.path().join(name), content).unwrap();
    }
    let mut server = spawn_for_test_multi(vec![
        ("proj-a".to_string(), vec![dir_a.path().to_path_buf()]),
        ("proj-b".to_string(), vec![dir_b.path().to_path_buf()]),
    ])
    .await
    .unwrap();
    server.keep_alive(dir_a);
    server.keep_alive(dir_b);
    server
}

async fn activate(ws: &mut Ws, name: &str) {
    let _: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: name.into(),
            open_last: false,
        },
    )
    .await;
}

/// A client standing in `workspace`.
async fn join_at(server: &aether_server::ServerHandle, workspace: &str) -> Ws {
    let mut ws = Ws::connect(server).await;
    activate(&mut ws, workspace).await;
    ws
}

async fn nav_step_from(
    ws: &mut Ws,
    buffer_id: u64,
    direction: Direction,
) -> Option<ViewOpenResult> {
    let result: NavStepResult = send_request::<NavStep>(
        ws,
        &NavStepParams {
            buffer_id,
            direction,
        },
    )
    .await;
    result.target
}

/// Wait for the server to finish tearing a disconnected client down — the socket closing and the
/// teardown running are two different moments, and the hand-over happens in the second.
async fn await_no_clients(server: &aether_server::ServerHandle) {
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
    loop {
        if server.state.lock().await.clients.is_empty() {
            return;
        }
        assert!(
            std::time::Instant::now() < deadline,
            "the disconnecting client was never torn down"
        );
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }
}

/// An entry recorded in one workspace is not steppable from another: A's trail is non-empty, and a
/// back step taken in B answers "no earlier location" rather than reaching across. B's own trail
/// works independently.
#[tokio::test]
async fn nav_history_does_not_cross_workspaces() {
    let server = two_workspaces().await;
    let mut ws = join_at(&server, "proj-a").await;
    let (a1, _) = nav_open_file(&mut ws, "a1.txt", None).await;
    let (_a2, _) = nav_open_file(&mut ws, "a2.txt", Some(a1)).await;

    activate(&mut ws, "proj-b").await;
    let (b1, _) = nav_open_file(&mut ws, "b1.txt", None).await;
    assert!(
        nav_step_from(&mut ws, b1, Direction::Backward)
            .await
            .is_none(),
        "A's trail is not B's — there is no earlier location here"
    );

    // B's own trail is a trail like any other.
    let (b2, _) = nav_open_file(&mut ws, "b2.txt", Some(b1)).await;
    assert_eq!(
        nav_step_from(&mut ws, b2, Direction::Backward)
            .await
            .map(|t| t.buffer_id),
        Some(b1),
        "B steps its own"
    );
    drop(server);
}

/// A → B → A leaves A's trail exactly as it was, in both directions: the switch neither clears it
/// nor carries it across.
#[tokio::test]
async fn nav_history_survives_a_workspace_round_trip() {
    let server = two_workspaces().await;
    let mut ws = join_at(&server, "proj-a").await;
    let (a1, _) = nav_open_file(&mut ws, "a1.txt", None).await;
    let (a2, _) = nav_open_file(&mut ws, "a2.txt", Some(a1)).await;
    let (a3, _) = nav_open_file(&mut ws, "a3.txt", Some(a2)).await;
    // Back: [a1, a2], forward: [a3] — both stacks carry something to lose.
    assert_eq!(
        nav_step_from(&mut ws, a3, Direction::Backward)
            .await
            .map(|t| t.buffer_id),
        Some(a2)
    );

    activate(&mut ws, "proj-b").await;
    let (b1, _) = nav_open_file(&mut ws, "b1.txt", None).await;
    assert!(nav_step_from(&mut ws, b1, Direction::Backward)
        .await
        .is_none());
    activate(&mut ws, "proj-a").await;
    let (a2_again, _) = nav_open_file(&mut ws, "a2.txt", None).await;
    assert_eq!(a2_again, a2, "the kept buffer survived the switch");

    // The back stack is where it was...
    assert_eq!(
        nav_step_from(&mut ws, a2, Direction::Backward)
            .await
            .map(|t| t.buffer_id),
        Some(a1),
        "A's back stack came back intact"
    );
    // ...and so is the forward stack, both the entry that step just pushed and the one recorded
    // before the round trip.
    assert_eq!(
        nav_step_from(&mut ws, a1, Direction::Forward)
            .await
            .map(|t| t.buffer_id),
        Some(a2)
    );
    assert_eq!(
        nav_step_from(&mut ws, a2, Direction::Forward)
            .await
            .map(|t| t.buffer_id),
        Some(a3),
        "A's forward stack came back intact"
    );
    drop(server);
}

/// A context keeps the trail of the last client to leave it: a fresh client activating A steps
/// back along the trail the disconnected one left behind.
#[tokio::test]
async fn a_fresh_client_inherits_the_trail_of_the_last_to_leave() {
    let server = two_workspaces().await;
    let mut ws1 = join_at(&server, "proj-a").await;
    let (a1, _) = nav_open_file(&mut ws1, "a1.txt", None).await;
    let (_a2, _) = nav_open_file(&mut ws1, "a2.txt", Some(a1)).await;
    drop(ws1);
    await_no_clients(&server).await;

    let mut ws2 = join_at(&server, "proj-a").await;
    let (a2_again, _) = nav_open_file(&mut ws2, "a2.txt", None).await;
    assert_eq!(
        nav_step_from(&mut ws2, a2_again, Direction::Backward)
            .await
            .map(|t| t.buffer_id),
        Some(a1),
        "the new window steps the trail the old one left"
    );
    drop(server);
}

/// The hand-over is a **copy**: a second client that picks up a context's trail steps its own, and
/// the window that left it behind still finds its trail where it was.
#[tokio::test]
async fn the_handed_over_trail_is_a_copy() {
    let server = two_workspaces().await;
    let mut ws1 = join_at(&server, "proj-a").await;
    let (a1, _) = nav_open_file(&mut ws1, "a1.txt", None).await;
    let (_a2, _) = nav_open_file(&mut ws1, "a2.txt", Some(a1)).await;
    // Leaving by switching, not by disconnecting: ws1 is still connected and still owns its trail.
    activate(&mut ws1, "proj-b").await;

    let mut ws2 = join_at(&server, "proj-a").await;
    let (a2_for_ws2, _) = nav_open_file(&mut ws2, "a2.txt", None).await;
    assert_eq!(
        nav_step_from(&mut ws2, a2_for_ws2, Direction::Backward)
            .await
            .map(|t| t.buffer_id),
        Some(a1),
        "the second window starts from the copy"
    );
    assert!(
        nav_step_from(&mut ws2, a1, Direction::Backward)
            .await
            .is_none(),
        "and it has spent that copy"
    );

    // ws1 comes back to a trail its neighbour's stepping never touched.
    activate(&mut ws1, "proj-a").await;
    let (a2_again, _) = nav_open_file(&mut ws1, "a2.txt", None).await;
    assert_eq!(
        nav_step_from(&mut ws1, a2_again, Direction::Backward)
            .await
            .map(|t| t.buffer_id),
        Some(a1),
        "stepping in one window did not move the other's trail"
    );
    drop(server);
}

// ---- search over a view -------------------------------------------------------------------------

/// A repo whose working tree differs from what was committed, its working-changes view open,
/// subscribed with the inline diff `diff_view`, and the whole of it loaded.
async fn working_changes(
    dir: &std::path::Path,
    committed: &[(&str, &str)],
    working: &[(&str, &str)],
    diff_view: bool,
) -> (
    aether_server::ServerHandle,
    Ws,
    ViewId,
    ViewportSubscribeResult,
) {
    let root = dir.canonicalize().unwrap();
    let repo = init_repo_at(&root);
    for (name, text) in committed {
        commit_file(&repo, name, text);
    }
    for (name, text) in working {
        std::fs::write(root.join(name), text).unwrap();
    }
    let (server, mut ws) = setup_repos_workspace(vec![root.clone()]).await;
    let opened: ViewOpenResult = show_buffer(
        &mut ws,
        &GitShowParams {
            repo_id: Some(root.to_string_lossy().into_owned()),
            buffer_id: None,
            target: ShowTarget::WorkingChanges,
            focus_path: None,
            record_nav_from: None,
        },
    )
    .await;
    let mut sub: ViewportSubscribeResult = send_request::<ViewportSubscribe>(
        &mut ws,
        &ViewportSubscribeParams {
            view_id: opened.view_id,
            cols: 120,
            rows: 200,
            overscan_rows: 0,
            scroll: ScrollPosition {
                element: 0,
                line: 0,
                sub_row: 0.0,
            },
            focus: None,
            wrap: WrapMode::None,
            continuation_marker_width: 0,
            tab_width: 4,
            diff_view,
        },
    )
    .await;
    sub.window = whole_view(&mut ws, sub.viewport_id, sub.window).await;
    (server, ws, opened.view_id, sub)
}

async fn search(
    ws: &mut Ws,
    view_id: ViewId,
    query: &str,
    anchor: Option<SearchAnchor>,
) -> SearchSetResult {
    send_request::<SearchSet>(
        ws,
        &SearchSetParams {
            view_id,
            query: query.into(),
            anchor,
            extend: false,
            from_selection: false,
            options: Default::default(),
        },
    )
    .await
}

async fn step(ws: &mut Ws, view_id: ViewId, direction: Direction, extend: bool) -> SearchNavResult {
    send_request::<SearchStep>(
        ws,
        &SearchStepParams {
            view_id,
            direction,
            extend,
            count: 1,
            set_query: None,
            options: Default::default(),
        },
    )
    .await
}

/// Every rendered line as `(element, buffer line, text, search ranges)`, in view order.
fn rendered_lines(
    window: &aether_protocol::viewport::Window,
) -> Vec<(
    u32,
    u32,
    String,
    Vec<aether_protocol::search::SearchMatchRange>,
)> {
    window
        .root
        .editors()
        .iter()
        .filter_map(|n| match n {
            Element::Editor { element, lines, .. } => Some((*element, lines)),
            _ => None,
        })
        .flat_map(|(element, lines)| {
            lines.iter().map(move |l| {
                let text: String = l
                    .visual_rows
                    .iter()
                    .flat_map(|r| r.segments.iter())
                    .map(|s| s.text.as_str())
                    .collect();
                (element, l.logical_line, text, l.search_matches.clone())
            })
        })
        .collect()
}

/// Files by name, with their text.
type Files = Vec<(&'static str, String)>;

/// Three hunks over two files: `fn FIRST`/`fn SECOND` far apart in `a.rs`, `fn THIRD` in `b.rs`.
fn three_changes() -> (Files, Files) {
    let file = |marks: &[(usize, &str)]| {
        let mut lines: Vec<String> = (0..40).map(|n| format!("fn line{n}() {{}}")).collect();
        for (at, name) in marks {
            lines[*at] = format!("fn {name}() {{}}");
        }
        format!("{}\n", lines.join("\n"))
    };
    (
        vec![("a.rs", file(&[])), ("b.rs", file(&[]))],
        vec![
            ("a.rs", file(&[(5, "FIRST"), (30, "SECOND")])),
            ("b.rs", file(&[(12, "THIRD")])),
        ],
    )
}

/// `/` searches every element of the view, not the one holding the cursor, and the count is a count
/// of what the view shows: the hunks' lines, and none of the files' other lines.
///
/// `n` walks every match once in view order — crossing from hunk to hunk and file to file the way
/// `j` does — and wraps at the end of the view.
#[tokio::test]
async fn search_covers_the_whole_view_and_n_crosses_its_elements() {
    let dir = tempfile::tempdir().unwrap();
    let (committed, working) = three_changes();
    let c: Vec<(&str, &str)> = committed.iter().map(|(n, t)| (*n, t.as_str())).collect();
    let w: Vec<(&str, &str)> = working.iter().map(|(n, t)| (*n, t.as_str())).collect();
    let (server, mut ws, view, sub) = working_changes(dir.path(), &c, &w, false).await;

    let lines = rendered_lines(&sub.window);
    let with_fn: Vec<(u32, u32)> = lines
        .iter()
        .filter(|(_, _, text, _)| text.contains("fn "))
        .map(|(e, l, _, _)| (*e, *l))
        .collect();
    let elements: std::collections::BTreeSet<u32> = with_fn.iter().map(|(e, _)| *e).collect();
    assert!(
        elements.len() >= 3,
        "three hunks, three elements: {elements:?}"
    );
    assert!(
        with_fn.len() < 80,
        "the hunks are a fraction of the two files"
    );

    let set = search(&mut ws, view, "fn ", None).await;
    assert_eq!(
        set.summary.total,
        with_fn.len() as u32,
        "every hunk's lines are matches, and nothing outside them is"
    );

    // Step once per match: each is visited exactly once, in view order, across every element.
    let mut focused = sub.focus.element;
    let mut visited = Vec::new();
    let mut crossings = 0;
    for _ in 0..with_fn.len() {
        let nav = step(&mut ws, view, Direction::Forward, false).await;
        if let Some(crossed) = &nav.crossed {
            assert_eq!(
                crossed.buffer.cursor, nav.cursor,
                "the rebind carries the landing"
            );
            focused = crossed.element;
            crossings += 1;
        }
        visited.push((
            (focused, nav.cursor.position.line),
            nav.summary.current_index,
        ));
    }
    assert!(crossings >= elements.len() - 1, "{crossings} crossings");
    let mut indices: Vec<u32> = visited.iter().map(|(_, i)| *i).collect();
    indices.sort_unstable();
    assert_eq!(
        indices,
        (1..=with_fn.len() as u32).collect::<Vec<_>>(),
        "every match once: {visited:?}"
    );
    let mut places: Vec<(u32, u32)> = visited.iter().map(|(p, _)| *p).collect();
    places.sort_unstable();
    assert_eq!(places, with_fn, "and each one is where the view shows it");
    // In view order: the indices climb by one, wrapping once from the last match to the first.
    for pair in visited.windows(2) {
        let (a, b) = (pair[0].1, pair[1].1);
        assert!(
            b == a + 1 || (a == with_fn.len() as u32 && b == 1),
            "{visited:?}"
        );
    }

    drop(server);
}

/// An incremental search anchors where the prompt opened — a position in a named element — and
/// lands on the first match at-or-after it in view order, moving focus there.
#[tokio::test]
async fn an_anchored_search_lands_at_or_after_its_element() {
    let dir = tempfile::tempdir().unwrap();
    let (committed, working) = three_changes();
    let c: Vec<(&str, &str)> = committed.iter().map(|(n, t)| (*n, t.as_str())).collect();
    let w: Vec<(&str, &str)> = working.iter().map(|(n, t)| (*n, t.as_str())).collect();
    let (server, mut ws, view, sub) = working_changes(dir.path(), &c, &w, false).await;
    let lines = rendered_lines(&sub.window);
    let (last_element, first_line) = lines
        .iter()
        .filter(|(_, _, t, _)| t.contains("fn "))
        .map(|(e, l, _, _)| (*e, *l))
        .max_by_key(|(e, _)| *e)
        .map(|(e, _)| {
            let first = lines
                .iter()
                .filter(|(el, _, t, _)| *el == e && t.contains("fn "))
                .map(|(_, l, _, _)| *l)
                .min()
                .unwrap();
            (e, first)
        })
        .unwrap();
    assert_ne!(sub.focus.element, last_element, "the anchor is elsewhere");

    let set = search(
        &mut ws,
        view,
        "fn ",
        Some(SearchAnchor {
            element: last_element,
            position: LogicalPosition {
                line: first_line,
                col: 0,
            },
        }),
    )
    .await;
    let crossed = set.crossed.expect("landing in another element moves focus");
    assert_eq!(crossed.element, last_element);
    assert_eq!(set.cursor.position.line, first_line);
    assert_eq!(
        set.cursor.anchor,
        LogicalPosition {
            line: first_line,
            col: 0
        },
        "the match is selected"
    );
    assert_eq!(
        set.summary.current_index,
        set.summary.total
            - lines
                .iter()
                .filter(|(e, _, t, _)| *e == last_element && t.contains("fn "))
                .count() as u32
            + 1,
        "the first match of the last element"
    );
    drop(server);
}

/// `Shift-n` grows the selection inside its element, and at the element's last match it does
/// nothing: the next match is in another element, and a selection lives in one buffer. Stopping
/// keeps the selection; carrying on would have to throw it away.
#[tokio::test]
async fn extending_stops_at_the_edge_of_its_element() {
    let dir = tempfile::tempdir().unwrap();
    let (committed, working) = three_changes();
    let c: Vec<(&str, &str)> = committed.iter().map(|(n, t)| (*n, t.as_str())).collect();
    let w: Vec<(&str, &str)> = working.iter().map(|(n, t)| (*n, t.as_str())).collect();
    let (server, mut ws, view, sub) = working_changes(dir.path(), &c, &w, false).await;
    search(&mut ws, view, "fn ", None).await;
    let start = sub.focus.buffer.cursor.anchor;

    let mut last = None;
    for _ in 0..40 {
        let nav = step(&mut ws, view, Direction::Forward, true).await;
        assert!(
            nav.crossed.is_none(),
            "an extending step never leaves its element"
        );
        assert_eq!(nav.cursor.anchor, start, "the anchor holds");
        if last == Some(nav.cursor) {
            break;
        }
        last = Some(nav.cursor);
    }
    let stopped = last.expect("it stepped");
    assert!(
        stopped.position.line > start.line,
        "it grew before it stopped: {stopped:?}"
    );
    // A plain step from there goes on into the next element.
    let on = step(&mut ws, view, Direction::Forward, false).await;
    assert!(on.crossed.is_some(), "the next match is in another element");
    drop(server);
}

/// `?` lands on text in the element it was pressed in, for the same reason: a match past it
/// leaves the cursor where the prompt opened.
#[tokio::test]
async fn select_to_match_stays_in_its_element() {
    let dir = tempfile::tempdir().unwrap();
    let (committed, working) = three_changes();
    let c: Vec<(&str, &str)> = committed.iter().map(|(n, t)| (*n, t.as_str())).collect();
    let w: Vec<(&str, &str)> = working.iter().map(|(n, t)| (*n, t.as_str())).collect();
    let (server, mut ws, view, sub) = working_changes(dir.path(), &c, &w, false).await;
    let at = sub.focus.buffer.cursor.position;
    let anchor = SearchAnchor {
        element: sub.focus.element,
        position: at,
    };
    // `THIRD` is only in `b.rs`, which the focused hunk of `a.rs` is not.
    let set: SearchSetResult = send_request::<SearchSet>(
        &mut ws,
        &SearchSetParams {
            view_id: view,
            query: "THIRD".into(),
            anchor: Some(anchor),
            extend: true,
            from_selection: false,
            options: Default::default(),
        },
    )
    .await;
    assert_eq!(set.summary.total, 1, "it is found");
    assert!(set.crossed.is_none());
    assert_eq!(
        (set.cursor.position, set.cursor.anchor),
        (at, sub.focus.buffer.cursor.anchor),
        "and the cursor stays where `?` was pressed"
    );
    drop(server);
}

/// A removed line the inline diff draws is searched while it is drawn: counted and painted with the
/// diff on, and `n` stops on it — seating the cursor on the line it sits above, since a removed line
/// holds no cursor. With the diff off it is not on screen and not counted.
///
/// The current match is the search's own: moving the cursor off clears it.
#[tokio::test]
async fn removed_lines_are_searched_while_the_diff_draws_them() {
    let dir = tempfile::tempdir().unwrap();
    let committed = "fn keep() {}\nfn OLDNAME() {}\nfn tail() {}\n";
    let working = "fn keep() {}\nfn NEWNAME() {}\nfn tail() {}\n";
    let (server, mut ws, view, sub) = working_changes(
        dir.path(),
        &[("a.rs", committed)],
        &[("a.rs", working)],
        false,
    )
    .await;

    let set = search(&mut ws, view, "OLDNAME", None).await;
    assert_eq!(
        set.summary.total, 0,
        "the diff is off, so the removed line is not on screen"
    );

    // The diff toggle re-renders, and the count rides the window it answers with.
    let on: ViewportWindowResult = send_request::<GitSetDiffView>(
        &mut ws,
        &GitSetDiffViewParams {
            viewport_id: sub.viewport_id,
            enabled: true,
        },
    )
    .await;
    assert_eq!(on.window.search.as_ref().map(|s| s.total), Some(1));

    let nav = step(&mut ws, view, Direction::Forward, false).await;
    assert_eq!(nav.summary.current_index, 1);
    assert_eq!(
        (nav.cursor.position, nav.cursor.anchor),
        (
            LogicalPosition { line: 1, col: 0 },
            LogicalPosition { line: 1, col: 0 }
        ),
        "seated on the line the removed one sits above, with nothing selected"
    );

    // Painted on the removed row, as the current match.
    let window = whole_view(&mut ws, sub.viewport_id, on.window).await;
    let rows: Vec<_> = window
        .root
        .lines()
        .iter()
        .flat_map(|l| l.baseline_above.iter())
        .filter(|r| r.text.contains("OLDNAME"))
        .map(|r| r.search_matches.clone())
        .collect();
    assert_eq!(
        rows,
        vec![vec![aether_protocol::search::SearchMatchRange {
            start: 3,
            end: 10,
            index: 1
        }]]
    );

    // Moving off it clears the current match — the one change that re-renders nothing, so it is
    // pushed.
    let buffer = nav
        .crossed
        .as_ref()
        .map_or(sub.focus.buffer.buffer_id, |c| c.buffer.buffer_id);
    let _ = move_cursor(
        &mut ws,
        &CursorMoveParams {
            buffer_id: buffer,
            motion: Motion::Char {
                direction: Direction::Forward,
                count: 1,
            },
            extend_selection: false,
        },
    )
    .await;
    let pushed = expect_notification_or_backlog::<SearchStateChanged>(&mut ws).await;
    assert_eq!(pushed.current_index, 0);

    // `n` from the line below steps back onto the removed row, which comes before its line.
    let back = step(&mut ws, view, Direction::Backward, false).await;
    assert_eq!(back.summary.current_index, 1);
    drop(server);
}

/// An ordinary file's own inline diff: its removed lines come from the file's diff against its
/// baseline rather than from a patch, and are searched the same way.
#[tokio::test]
async fn a_files_own_diff_is_searched_too() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path().canonicalize().unwrap();
    let repo = init_repo_at(&root);
    commit_file(&repo, "a.rs", "fn keep() {}\nfn OLDNAME() {}\n");
    std::fs::write(root.join("a.rs"), "fn keep() {}\nfn NEWNAME() {}\n").unwrap();
    let (server, mut ws) = setup_repos_workspace(vec![root.clone()]).await;
    let buffer = open_test_buffer(&mut ws, "a.rs").await;
    let view = view_of(buffer);
    let sub: ViewportSubscribeResult = send_request::<ViewportSubscribe>(
        &mut ws,
        &ViewportSubscribeParams {
            view_id: view,
            cols: 120,
            rows: 50,
            overscan_rows: 0,
            scroll: ScrollPosition::default(),
            focus: None,
            wrap: WrapMode::None,
            continuation_marker_width: 0,
            tab_width: 4,
            diff_view: true,
        },
    )
    .await;
    // The baseline attaches asynchronously; wait for the file's diff before searching it.
    let mut total = 0;
    for _ in 0..100 {
        total = search(&mut ws, view, "OLDNAME", None).await.summary.total;
        if total == 1 {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }
    assert_eq!(total, 1);
    let nav = step(&mut ws, view, Direction::Forward, false).await;
    assert_eq!(nav.cursor.position, LogicalPosition { line: 1, col: 0 });
    let _ = sub;
    drop(server);
}

/// What changes a search's count mostly changes the view too, and the count rides the re-render: an
/// edit that adds a match reports the new total on the window it pushes.
#[tokio::test]
async fn the_count_rides_the_window_an_edit_pushes() {
    let (server, mut ws, buffer_id) = setup_with_buffer("foo\n").await;
    let view = view_of(buffer_id);
    let _sub: ViewportSubscribeResult = send_request::<ViewportSubscribe>(
        &mut ws,
        &ViewportSubscribeParams {
            view_id: view,
            cols: 80,
            rows: 24,
            overscan_rows: 0,
            scroll: ScrollPosition::default(),
            focus: None,
            wrap: WrapMode::None,
            continuation_marker_width: 0,
            tab_width: 4,
            diff_view: false,
        },
    )
    .await;
    let set = search(&mut ws, view, "foo", None).await;
    assert_eq!(set.summary.total, 1);
    assert!(
        set.summary.generation > 0,
        "a search's matches carry their generation"
    );
    let _: EditResult = send_request::<InputText>(
        &mut ws,
        &InputTextParams {
            buffer_id,
            text: "foo ".into(),
            select_pasted: false,
            at: None,
            replace_selection: false,
        },
    )
    .await;
    // The set's own repaint can arrive after its reply; the edit's is the one at a later revision.
    let edited = loop {
        let p = expect_notification_or_backlog::<ViewportLinesChanged>(&mut ws).await;
        if p.revision > 0 {
            break p;
        }
    };
    let summary = edited.window.search.expect("the count rides the window");
    assert_eq!(summary.total, 2);
    assert!(
        summary.generation > set.summary.generation,
        "found afresh after the edit, so a later generation — what tells a client the window has \
         caught up with the marks"
    );
    drop(server);
}
